package ktanesolver.module.modded.regular.factorymaze;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class FactoryMazeSolverTest{@Test void findsThreeUnlocksAndPersistsStartRoom(){var m=new ModuleEntity();var r=new FactoryMazeSolver().solve(new RoundEntity(),new BombEntity(),m,new FactoryMazeInput(1,1,List.of("Bathroom","Assembly Line","Cafeteria","Room A9","Broom Closet"),List.of(true,true,true,true,true)));var o=((SolveSuccess<FactoryMazeOutput>)r).output();assertThat(o.actions().stream().filter("unlock"::equals).count()).isEqualTo(3);assertThat(o.startRoom()).isEqualTo("Bathroom");assertThat(m.getState()).containsEntry("factoryMazeStartRoom","Bathroom");}}
